import argparse
import html
import json
from pathlib import Path


def revenue_card(orders):
    return '<section aria-label="Revenue"><strong>Unavailable</strong></section>'


def order_count(orders):
    return len(orders)


def render(orders):
    return '<main>' + revenue_card(orders) + f'<p>Orders: {order_count(orders)}</p></main>'


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--data', type=Path, default=Path('orders.json'))
    parser.add_argument('--health', action='store_true')
    args = parser.parse_args()
    print('ok' if args.health else render(json.loads(args.data.read_text())))

