import unittest
from dashboard import revenue_card


class RevenueTests(unittest.TestCase):
    def test_paid_only(self):
        orders = [{'state': 'paid', 'cents': 1005}, {'state': 'pending', 'cents': 3000}]

        card = revenue_card(orders)

        self.assertIn('$10.05', card)

    def test_empty(self):
        self.assertIn('$0.00', revenue_card([]))

